### DFS C 구현 (인접 행렬)

```c
#include <stdio.h>
#include <stdlib.h>

#define TRUE 1
#define FALSE 0
#define MAX_VERTICES 50

typedef struct {
    int n;  // 정점의 개수
    int adj_mat[MAX_VERTICES][MAX_VERTICES];
} GraphType;

int visited[MAX_VERTICES];

void init(GraphType *g) {
    g->n = 0;
    for (int r = 0; r < MAX_VERTICES; r++)
        for (int c = 0; c < MAX_VERTICES; c++)
            g->adj_mat[r][c] = 0;
}

void insert_vertex(GraphType *g, int v) { g->n++; }

void insert_edge(GraphType *g, int s, int e) {
    g->adj_mat[s][e] = 1;
    g->adj_mat[e][s] = 1;
}

// 인접 행렬 버전 DFS
void dfs_mat(GraphType *g, int v) {
    visited[v] = TRUE;
    printf("정점 %d -> ", v);

    for (int w = 0; w < g->n; w++)
        if (g->adj_mat[v][w] && !visited[w])
            dfs_mat(g, w);
}

int main(void) {
    GraphType *g = (GraphType*)malloc(sizeof(GraphType));
    init(g);
    for (int i = 0; i < 4; i++) insert_vertex(g, i);
    insert_edge(g, 0, 1);
    insert_edge(g, 0, 2);
    insert_edge(g, 1, 2);
    insert_edge(g, 2, 3);

    dfs_mat(g, 0);
    // 출력: 정점 0 -> 정점 1 -> 정점 2 -> 정점 3 ->
    free(g);
    return 0;
}
```

### 명시적 스택을 이용한 DFS (반복문)

```
DFS-iterative(G, v):
  스택 S 생성
  S.push(v)
  while S가 비어있지 않으면:
    v = S.pop()
    if v가 방문되지 않았으면:
      v 방문 표시
      for u ∈ v의 인접 정점:
        if u 미방문: S.push(u)
```

